-- Função para verificar se o jogo atual é suportado
local function isGameSupported()
    local currentPlaceId = game.PlaceId
    local supportedIds = SUPPORTED_GAME_IDS
    for i = 1, #supportedIds do
        if currentPlaceId == supportedIds[i] then
            return true
        end
    end
    return false
end

