-- Função de shake
local function ShakeFrame(frame)
    local originalPos = frame.Position
    local shakeTime = 0.05
    local intensity = 5
    task_spawn(function()
        for i = 1, 6 do
            local targetPos = originalPos + UDim2_new(0, (i % 2 == 0 and intensity or -intensity), 0, 0)
            TweenService:Create(frame, TweenInfo_new(shakeTime, Enum.EasingStyle.Sine), {Position = targetPos}):Play()
            task_wait(shakeTime)
        end
        TweenService:Create(frame, TweenInfo_new(shakeTime, Enum.EasingStyle.Quad), {Position = originalPos}):Play()
    end)
end

