        marcarComoFechado()
    end

    CloseBtn.MouseButton1Click:Connect(CloseGUI)

    -- Animação de entrada
    task_spawn(function()
        MainFrame.Size = UDim2_new(0, 0, 0, 0)
        MainFrame.BackgroundTransparency = 1
        
        TweenService:Create(BackgroundOverlay, TweenInfo_new(0.4), {BackgroundTransparency = 0.8}):Play()
        TweenService:Create(MainFrame, TweenInfo_new(0.6, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {
            Size = UDim2_new(0, 450, 0, 500),
            BackgroundTransparency = 0.05
        }):Play()
    end)

    -- Efeitos hover nos botões
    ValidateButton.MouseEnter:Connect(function()
        TweenService:Create(ValidateButton, TweenInfo_new(0.2), {BackgroundColor3 = Color3_fromRGB(158, 63, 246)}):Play()
    end)
    
    ValidateButton.MouseLeave:Connect(function()
        TweenService:Create(ValidateButton, TweenInfo_new(0.2), {BackgroundColor3 = CurrentTheme}):Play()
    end)

    GetKeyButton.MouseEnter:Connect(function()
        TweenService:Create(GetKeyButton, TweenInfo_new(0.2), {BackgroundColor3 = Color3_fromRGB(70, 120, 220)}):Play()
    end)
    
    GetKeyButton.MouseLeave:Connect(function()
        TweenService:Create(GetKeyButton, TweenInfo_new(0.2), {BackgroundColor3 = Color3_fromRGB(40, 40, 50)}):Play()
    end)

    -- Lógica do Timer de Cópia Persistente
    local isCooldown = false
    local function startCooldown(seconds)
        isCooldown = true
        GetKeyButton.Interactable = false
        
        task_spawn(function()
            local originalText = "COPY KEY LINK"
            local remaining = seconds
            while remaining > 0 do
                local mins = math.floor(remaining / 60)
                local secs = remaining % 60
                GetKeyButton.Text = string.format("WAIT %02d:%02d", mins, secs)
                GetKeyButton.BackgroundColor3 = Color3_fromRGB(60, 60, 70)
                task_wait(1)
                remaining = remaining - 1
                if not GetKeyButton or not GetKeyButton.Parent then break end
            end
            if GetKeyButton and GetKeyButton.Parent then
                isCooldown = false
                GetKeyButton.Interactable = true
                GetKeyButton.Text = originalText
                GetKeyButton.BackgroundColor3 = Color3_fromRGB(40, 40, 50)
            end
        end)
    end

    -- Verificar se já existe um timer salvo ao abrir
    local timeLeft = getRemainingCooldown()
    if timeLeft > 0 then
        startCooldown(timeLeft)
    end

    -- Lógica para copiar link da key
    GetKeyButton.MouseButton1Click:Connect(function()
        if isCooldown then return end
        
        local secureGetKeyLink = Junkie.get_key_link()
        if not secureGetKeyLink then
            GetKeyButton.Text = "ERROR!"
            GetKeyButton.BackgroundColor3 = Color3_fromRGB(255, 60, 60)
            task_wait(1.5)
            GetKeyButton.Text = "COPY KEY LINK"
            GetKeyButton.BackgroundColor3 = Color3_fromRGB(40, 40, 50)
            return
        end
        
        if setclipboard then
            setclipboard(secureGetKeyLink)
            GetKeyButton.Text = "COPIED!"
            GetKeyButton.BackgroundColor3 = Color3_fromRGB(80, 200, 80)
            
            -- Efeito de confirmação
            task_spawn(function()
                local originalSize = GetKeyButton.Size
                TweenService:Create(GetKeyButton, TweenInfo_new(0.1), {
                    Size = UDim2_new(1.02, 0, 0, 47)
                }):Play()
                task_wait(0.1)
                TweenService:Create(GetKeyButton, TweenInfo_new(0.1), {
                    Size = originalSize
                }):Play()
            end)
            
            task_wait(1)
            saveTimer()
            startCooldown(300)
            ShowNotification("Success", "Key link copied to clipboard!", 3)
        else
            print("Key Link:", secureGetKeyLink)
            saveTimer()
            startCooldown(300)
            ShowNotification("Info", "Key link printed to console", 3)
        end
    end)

    -- Lógica de Validação da Key
    ValidateButton.MouseButton1Click:Connect(function()
        if not ValidateButton.Interactable then return end
        
        local key = KeyInput.Text:gsub("%s+", "")
        if #key == 0 then
            -- Efeito de erro no input
            InputStroke.Color = Color3_fromRGB(255, 50, 50)
            ShakeFrame(InputFrame)
            ShowNotification("Error", "Please enter a key", 3)
            return
        end
        
        -- Animação de loading
        ValidateButton.Text = "VERIFYING..."
        ValidateButton.Interactable = false
        KeyInput.Interactable = false
        
        task_spawn(function()
            local result = Junkie.check_key(key)
            
            if result and result.valid then
                -- Efeito de sucesso
                InputStroke.Color = Color3_fromRGB(50, 255, 100)
                
                ValidateButton.Text = "✓ SUCCESS"
                ValidateButton.BackgroundColor3 = Color3_fromRGB(80, 200, 80)
                
                -- Efeito de confirmação
                task_spawn(function()
                    local originalSize = ValidateButton.Size
                    for i = 1, 2 do
                        TweenService:Create(ValidateButton, TweenInfo_new(0.1), {
                            Size = UDim2_new(1.03, 0, 0, 52)
                        }):Play()
                        task_wait(0.1)
                        TweenService:Create(ValidateButton, TweenInfo_new(0.1), {
                            Size = originalSize
                        }):Play()
                        task_wait(0.1)
                    end
                end)
                
                saveVerifiedKey(key)
                getgenv().SCRIPT_KEY = key
                
                ShowNotification("Welcome", "Key validated successfully!", 3)
                task_wait(1)
                CloseGUI()
                main()
            else
                -- Efeito de erro
                InputStroke.Color = Color3_fromRGB(255, 50, 50)
                
                ValidateButton.Text = "✗ INVALID KEY"
                ValidateButton.BackgroundColor3 = Color3_fromRGB(255, 80, 80)
                
                ShakeFrame(InputFrame)
                ShakeFrame(MainFrame)
                ShowNotification("Error", "Invalid license key", 3)
                
                task_wait(2)
                ValidateButton.Text = "VALIDATE KEY"
                ValidateButton.Interactable = true
                KeyInput.Interactable = true
                ValidateButton.BackgroundColor3 = CurrentTheme
                InputStroke.Color = CurrentTheme
            end
        end)
    end)

    -- Focus no input
    KeyInput.Focused:Connect(function()
        InputStroke.Thickness = 2.5
    end)
    
    KeyInput.FocusLost:Connect(function()
        InputStroke.Thickness = 2
    end)

    -- Permitir fechar com ESC
    local escConnection
    escConnection = UserInputService.InputBegan:Connect(function(input, gameProcessed)
        if input.KeyCode == Enum.KeyCode.Escape then
            escConnection:Disconnect()
            CloseGUI()
        end
    end)

    -- Arrastar a janela
    local dragging, dragInput, dragStart, startPos
    TopBar.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            dragging = true 
            dragStart = input.Position 
            startPos = MainFrame.AbsolutePosition
            input.Changed:Connect(function() 
                if input.UserInputState == Enum.UserInputState.End then 
                    dragging = false 
                end 
            end)
        end
    end)
    
    TopBar.InputChanged:Connect(function(input) 
        if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then 
            dragInput = input 
        end 
    end)
    
    UserInputService.InputChanged:Connect(function(input) 
        if input == dragInput and dragging then 
            local delta = input.Position - dragStart
            local screenSize = KeyScreenGui.AbsoluteSize
            local frameSize = MainFrame.AbsoluteSize
            local newPosX = math.clamp(startPos.X + delta.X, 0, screenSize.X - frameSize.X)
            local newPosY = math.clamp(startPos.Y + delta.Y, 0, screenSize.Y - frameSize.Y)
            MainFrame.Position = UDim2_new(0, newPosX + (frameSize.X * MainFrame.AnchorPoint.X), 0, newPosY + (frameSize.Y * MainFrame.AnchorPoint.Y))
        end 
    end)

    return KeyScreenGui
end

-- Verificação inicial da key salva
local savedKey = loadVerifiedKey()
if savedKey then
    local result = Junkie.check_key(savedKey)
    if result and result.valid then
        getgenv().SCRIPT_KEY = savedKey
        ShowNotification("Vortex Hub", "Welcome back! Loading hub...", 3)
        main()
    else
        clearSavedKey()
        task_wait(1)
        KeySystem:CreateKeyGUI()
    end
else
    task_wait(1)
    KeySystem:CreateKeyGUI()
end

